  socket.on('createClubTable', async (data: { clubId: number; config: any }) => {
    const auth = authSessions.get(socket.id);
    if (!auth) { socket.emit('error', { message: 'Not authenticated' }); return; }
    // 2026-10-11 (R1, AUTH-4) — the club table's numbers become a real cash
    // table's buy-in: validated before anything is stored (same rules as a
    // home game; clubManager's own defaults for absent fields).
    const ctCheck = validateTableConfig(data?.config, {
      tableName: '', smallBlind: 5, bigBlind: 10, ante: 0, minBuyIn: (bb) => bb * 20, maxBuyIn: (bb) => bb * 100,
    });
    if (!ctCheck.ok) { socket.emit('error', { message: ctCheck.error, code: ctCheck.code }); return; }
    const result = await createClubTable(auth.userId, data.clubId, ctCheck.config);
    if (result.success && result.table) {
      // Create a real table in the TableManager — R2 (CLUBS-4): the same
      // helper that re-creates it after a redeploy (ensureClubRuntimeTable).
      const tableId = await createClubRuntimeTable(data.clubId, { ...result.table, maxSeats: ctCheck.config.maxSeats ?? result.table.maxSeats });
      if (tableId) {
        await updateClubTableId(result.table.id, tableId);
        result.table.tableId = tableId;
      }
      socket.emit('clubTableCreated', { success: true, table: result.table });
    } else {
      socket.emit('error', { message: result.error });
    }
  });

  socket.on('getClubTables', async (data: { clubId: number }) => {
    const result = await getClubTables(data.clubId);
    // R2 (CLUBS-4) — a table a redeploy dropped is re-created for the list (a joinable id).
    for (const t of result.tables || []) {
      try { await ensureClubRuntimeTable(t); } catch (e: any) { console.warn('[Clubs] club table re-create failed:', e?.message || e); }
    }
    socket.emit('clubTables', result);
  });

  socket.on('joinClubTable', async (data: { clubTableId: number; playerName: string; seatIndex: number; buyIn: number; avatar?: string }) => {
    // 2026-10-07 play gate (joinTable re-checks; the result is cached).
    const ctGate = await assertPlayable(socket, 'joinClubTable');
    if (ctGate) { emitPlayRefusal(socket, ctGate); return; }
    const auth = authSessions.get(socket.id);
    if (!auth) { socket.emit('error', { message: 'Not authenticated' }); return; }

    const clubTable = await getClubTableById(data.clubTableId);
    if (!clubTable) { socket.emit('error', { message: 'Club table not found' }); return; }
    if (!(await isClubMember(clubTable.clubId, auth.userId))) {
      socket.emit('error', { message: 'You must be a club member to join this table' });
      return;
    }
    // R2 (CLUBS-4) — its runtime table, re-created from the stored config if a
    // redeploy dropped it (it used to answer "not yet created" forever).
    let runtimeTableId: string | null = null;
    try { runtimeTableId = await ensureClubRuntimeTable(clubTable); } catch (e: any) { console.warn('[Clubs] club table re-create failed:', e?.message || e); }
    if (!runtimeTableId) {
      socket.emit('error', { message: clubTable.isActive ? 'This club table is not available right now. Ask a manager to check it.' : 'This club table was closed.', code: 'club_table_unavailable' });
      return;
    }

    // Redirect to the standard joinTable handler by triggering the same event on this socket.
    // R2 (C1) — joinTable refuses a club table to everyone else; this payload
    // object carries the membership grant (clubJoinGrants — a client frame can
    // never be one of these objects).
    const listeners = socket.listeners('joinTable');
    if (listeners.length > 0) {
      const grantedPayload = {
        tableId: runtimeTableId,
        playerName: data.playerName,
        seatIndex: data.seatIndex,
        buyIn: data.buyIn,
        avatar: data.avatar,
      };
      clubJoinGrants.add(grantedPayload);
      return (listeners[0] as Function)(grantedPayload);
    }
  });

  socket.on('searchClubs', async (data: { query: string }) => {
    const result = await searchClubs(data.query || '');
    socket.emit('clubSearchResults', result);
  });

  socket.on('updateClubSettings', async (data: { clubId: number; settings: any }) => {
    const auth = authSessions.get(socket.id);
    if (!auth) { socket.emit('error', { message: 'Not authenticated' }); return; }
    const result = await updateClubSettings(auth.userId, data.clubId, data.settings);
    if (result.success) {
      socket.emit('clubSettingsUpdated', result);
    } else {
      socket.emit('error', { message: result.error });
    }
  });

  socket.on('deleteClub', async (data: { clubId: number }) => {
    const auth = authSessions.get(socket.id);
    if (!auth) { socket.emit('error', { message: 'Not authenticated' }); return; }
    const result = await deleteClub(auth.userId, data.clubId);
    if (result.success) {
      // F103 (2026-10-21) — its club tournaments not yet started were cancelled
      // and every registration refunded in the delete's transaction: audited and
      // told like a cancel (cancelClubTournament's notice, reason club_deleted).
      for (const r of result.refunded || []) {
        if (r.paid > 0) auditLog(String(r.userId), 'CLUB_TOURNAMENT_REFUND', { clubTournamentId: r.tournamentId, amount: r.paid, reason: 'club_deleted' });
        for (const [sid, a] of authSessions) {
          if (a.userId !== r.userId) continue;
          io.sockets.sockets.get(sid)?.emit('clubTournamentCancelled', { tournamentId: r.tournamentId, clubId: data.clubId, refunded: r.paid, reason: 'club_deleted' });
        }
      }
      clubTournamentStats.cancelledBeforeStart += (result.cancelled || []).length;
      socket.emit('clubDeleted', { clubId: data.clubId });
    } else {
      socket.emit('error', { message: result.error, ...(result.code ? { code: result.code } : {}) });
    }
  });

  // ─── Club Chat & Messages ───

  socket.on('joinClubRoom', async (data: { clubId: number }) => {
    const auth = authSessions.get(socket.id);
    if (!auth) return;
    if (!(await isClubMember(data.clubId, auth.userId))) return;
    socket.join(`club:${data.clubId}`);
  });

  socket.on('leaveClubRoom', async (data: { clubId: number }) => {
    socket.leave(`club:${data.clubId}`);
  });

  socket.on('sendClubMessage', async (data: { clubId: number; message: string; type?: 'chat' | 'announcement' | 'system' }) => {
    const auth = authSessions.get(socket.id);
    if (!auth) { socket.emit('error', { message: 'Not authenticated' }); return; }
    if (!(await isClubMember(data.clubId, auth.userId))) { socket.emit('error', { message: 'Not a club member' }); return; }

    // Rate limit: min 800ms between messages per socket (reuses lastChatTime map)
    const now = Date.now();
    const last = lastChatTime.get(socket.id) || 0;
    if (now - last < 800) {
      socket.emit('error', { message: 'Chat rate limited' });
      return;
    }
    lastChatTime.set(socket.id, now);

    // Validate message length
    const msgText = typeof data.message === 'string' ? data.message.trim().slice(0, 500) : '';
    if (!msgText) { socket.emit('error', { message: 'Empty message' }); return; }

    const msgType = data.type || 'chat';
    const result = await sendClubMessage(data.clubId, auth.userId, seatNameForSocket(socket), msgText, msgType);   // R1 contract #3
    if (result.success && result.message) {
      io.to(`club:${data.clubId}`).emit('clubMessage', result.message);
      if (msgType === 'announcement') {
        await addActivity(data.clubId, 'announcement', { username: seatNameForSocket(socket), message: data.message });
      }
    } else {
      socket.emit('error', { message: result.error });
    }
  });

  // Gate a PRIVATE club read/mutation on active membership (audit H4/H5,
  // 2026-07-01). Returns the caller's role in the club, or null after emitting
  // an error. Previously the whole get* batch (chat, activity, member stats)
  // and pinClubMessage had zero membership checks, so any socket could
  // enumerate a clubId and read private chat history / member rosters / stats,
  // or pin/unpin arbitrary messages in a club it doesn't belong to.
  const requireClubMember = async (clubId: number): Promise<string | null> => {
    const auth = authSessions.get(socket.id);
    if (!auth) { socket.emit('error', { message: 'Not authenticated' }); return null; }
    if (!Number.isFinite(Number(clubId))) { socket.emit('error', { message: 'Invalid club' }); return null; }
    const role = await getMemberRole(Number(clubId), auth.userId);
    if (!role) { socket.emit('error', { message: 'You must be a member of this club' }); return null; }
    return role;
  };

  socket.on('getClubMessages', async (data: { clubId: number; limit?: number }) => {
    if (!(await requireClubMember(data.clubId))) return;
    const result = await getClubMessages(data.clubId, data.limit || 50);
    socket.emit('clubMessages', result);
  });

  socket.on('getClubAnnouncements', async (data: { clubId: number }) => {
    const result = await getAnnouncements(data.clubId);
    socket.emit('clubAnnouncements', result);
  });

  socket.on('pinClubMessage', async (data: { clubId: number; messageId: number; pin: boolean }) => {
    // H5: pinning is a moderation action — require an elevated club role, not
    // just any authenticated socket. Previously any logged-in user could pin/
    // unpin messages in any club (IDOR), broadcast to that club's room.
    const role = await requireClubMember(data.clubId);
    if (!role) return;
    if (role !== 'owner' && role !== 'manager') {
      socket.emit('error', { message: 'Only club owners/managers can pin messages' });
      return;
    }
    const result = data.pin ? await pinMessage(data.clubId, data.messageId) : await unpinMessage(data.clubId, data.messageId);
    if (result.success) {
      io.to(`club:${data.clubId}`).emit('clubMessagePinned', { messageId: data.messageId, pinned: data.pin });
    } else {
      socket.emit('error', { message: result.error });
    }
  });

  // ─── Club Leaderboard & Stats ───

  socket.on('getClubLeaderboard', async (data: { clubId: number; period?: 'today' | 'week' | 'alltime' }) => {
    // 2026-07-05 audit P2 fix: membership-gate club-scoped reads. This returned a
    // private club's member usernames + chip win/loss stats to ANY authenticated
    // socket with the clubId (the H4/H5 membership-check pattern was applied to
    // getClubMessages/getClubStatistics/getActivityFeed but not here).
    if (!(await requireClubMember(data.clubId))) return;
    const result = await getClubLeaderboard(data.clubId, data.period || 'alltime');
    socket.emit('clubLeaderboard', result);
  });

  socket.on('getClubStatistics', async (data: { clubId: number }) => {
    if (!(await requireClubMember(data.clubId))) return;
    const result = await getClubStatistics(data.clubId);
    socket.emit('clubStatistics', result);
  });

  // ─── Club Activity Feed ───

  socket.on('getClubActivity', async (data: { clubId: number; limit?: number }) => {
    if (!(await requireClubMember(data.clubId))) return;
    const result = await getActivityFeed(data.clubId, data.limit || 20);
    socket.emit('clubActivity', result);
  });

  // ========== Club Tournaments ==========

  socket.on('createClubTournament', async (data: { clubId: number; config: any }) => {
    const auth = authSessions.get(socket.id);
    if (!auth) { socket.emit('error', { message: 'Not authenticated' }); return; }
    // 2026-06-11 audit R13: signature is (clubId, managerId, config). This was
    // called (managerId, clubId, ...) — swapped — so getMemberRole(clubId=userId,
    // managerId=clubId) never matched, and EVERY owner/manager got "Only owners
    // and managers can create tournaments".
    const result = await createClubTournament(data.clubId, auth.userId, data.config);
    if (result.success) {
      socket.emit('clubTournamentCreated', result);
    } else {
      socket.emit('error', { message: result.error });
    }
  });

  socket.on('getClubTournaments', async (data: { clubId: number }) => {
    // 2026-07-05 audit P2 fix: membership-gate (was leaking a private club's
    // tournament configs/buy-ins/participants to any authenticated caller).
    if (!(await requireClubMember(data.clubId))) return;
    const result = await getClubTournaments(data.clubId);
    socket.emit('clubTournaments', result);
  });

  socket.on('registerClubTournament', async (data: { tournamentId: number }) => {
    const crGate = await assertPlayable(socket, 'registerClubTournament'); // 2026-10-07 play gate
    if (crGate) { emitPlayRefusal(socket, crGate); return; }
    const auth = authSessions.get(socket.id);
    if (!auth) { socket.emit('error', { message: 'Not authenticated' }); return; }
    // R2 (TOURNEY-14) — the buy-in is CHARGED with the registration (one
    // transaction) and an unregister (the same toggle) refunds what it paid.
    const result = await registerForClubTournament(Number(data?.tournamentId), auth.userId);
    if (result.success) {
      if (result.registered && (result.charged || 0) > 0) {
        clubTournamentStats.buyIns++;
        auditLog(auth.username, 'CLUB_TOURNAMENT_BUYIN', { clubTournamentId: Number(data?.tournamentId), amount: result.charged });
      }
      if (!result.registered && (result.refunded || 0) > 0) {
        clubTournamentStats.unregisterRefunds++;
        auditLog(auth.username, 'CLUB_TOURNAMENT_REFUND', { clubTournamentId: Number(data?.tournamentId), amount: result.refunded, reason: 'unregistered' });
      }
      socket.emit('clubTournamentRegistered', {
        tournamentId: data.tournamentId, registered: result.registered,
        ...(result.charged ? { charged: result.charged } : {}), ...(result.refunded ? { refunded: result.refunded } : {}),
      });
    } else {
      socket.emit('error', { message: result.error, ...(result.code ? { code: result.code } : {}) });
    }
  });

  // R2 (TOURNEY-14) — the start is REAL: the paid registrations become a live
  // tournament (launchClubTournament — dealt through the shared start path);
  // it used to flip a status column and deal nothing.
  socket.on('startClubTournament', async (data: { tournamentId: number }) => {
    const auth = authSessions.get(socket.id);
    if (!auth) { socket.emit('error', { message: 'Not authenticated' }); return; }
    const result = await startClubTournament(Number(data?.tournamentId), auth.userId);
    if (!result.success || !result.tournament || !result.entrants) {
      socket.emit('error', { message: result.error, ...(result.code ? { code: result.code } : {}) });
      return;
    }
    for (const r of result.refunded || []) {
      if (r.paid > 0) auditLog(String(r.userId), 'CLUB_TOURNAMENT_REFUND', { clubTournamentId: result.tournament.id, amount: r.paid, reason: 'not_paid_in_full_at_start' });
    }
    let liveId: string | null = null;
    try {
      liveId = await launchClubTournament({ tournament: result.tournament, entrants: result.entrants });
    } catch (e: any) {
      // The claim stands (running) with every buy-in transferred: refund them all.
      clubTournamentStats.startFailed++;
      console.error('[ClubTournament] start failed — refunding the entrants:', e?.message || e);
      void refundClubTournamentEntrants(result.tournament.id, '', result.entrants.map((x) => ({ userId: x.userId, amount: x.paid })), 'start_failed');
      socket.emit('error', { message: 'Could not start the tournament — every buy-in was refunded.', code: 'start_failed' });
      return;
    }
    socket.emit('clubTournamentStarted', { tournamentId: data.tournamentId, liveTournamentId: liveId, entrants: result.entrants.length });
    broadcastTournamentList();
  });

  // R2 (TOURNEY-14) — cancel BEFORE the start (owner / manager): every
  // registration refunded what it paid, each member told.
  socket.on('cancelClubTournament', async (data: { tournamentId: number }) => {
    const auth = authSessions.get(socket.id);
    if (!auth) { socket.emit('error', { message: 'Not authenticated' }); return; }
    const tid = Number(data?.tournamentId);
    const result = await cancelClubTournament(tid, auth.userId);
    if (!result.success) { socket.emit('error', { message: result.error, ...(result.code ? { code: result.code } : {}) }); return; }
    clubTournamentStats.cancelledBeforeStart++;
    for (const r of result.refunded || []) {
      if (r.paid > 0) auditLog(String(r.userId), 'CLUB_TOURNAMENT_REFUND', { clubTournamentId: tid, amount: r.paid, reason: 'cancelled_by_club' });
      for (const [sid, a] of authSessions) {
        if (a.userId !== r.userId) continue;
        io.sockets.sockets.get(sid)?.emit('clubTournamentCancelled', { tournamentId: tid, clubId: result.clubId, refunded: r.paid, reason: 'cancelled_by_club' });
      }
    }
    socket.emit('clubTournamentCancelled', { tournamentId: tid, clubId: result.clubId, refundedPlayers: (result.refunded || []).length, reason: 'cancelled_by_club' });
  });

  // ========== Club Challenges ==========

  socket.on('createClubChallenge', async (data: { clubId: number; challengedId: number; stakes: number }) => {
    const ccGate = await assertPlayable(socket, 'createClubChallenge'); // 2026-10-07 play gate
    if (ccGate) { emitPlayRefusal(socket, ccGate); return; }
    const auth = authSessions.get(socket.id);
    if (!auth) { socket.emit('error', { message: 'Not authenticated' }); return; }
    // 2026-10-11 (R1, AUTH-4) — the stakes ARE both players' buy-in (the
    // challenge table's minBuyIn): a whole number of chips in range, never 0 /
    // negative / fractional / huge.
    const csCheck = validateChallengeStakes(data?.stakes);
    if (!csCheck.ok) { socket.emit('error', { message: csCheck.error, code: csCheck.code }); return; }
    const result = await createChallenge(data.clubId, auth.userId, data.challengedId, csCheck.stakes);
    if (result.success) {
      socket.emit('clubChallengeCreated', result);
    } else {
      socket.emit('error', { message: result.error });
    }
  });

  socket.on('acceptClubChallenge', async (data: { challengeId: number }) => {
    // 2026-10-07 play gate — before acceptChallenge() mutates the challenge
    // and a table is spawned for both players.
    const caGate = await assertPlayable(socket, 'acceptClubChallenge');
    if (caGate) { emitPlayRefusal(socket, caGate); return; }
    const auth = authSessions.get(socket.id);
    if (!auth) { socket.emit('error', { message: 'Not authenticated' }); return; }
    const result = await acceptChallenge(data.challengeId, auth.userId);
    if (!result.success || !result.challenge) { socket.emit('error', { message: result.error }); return; }
    const { id: challengeId, challengerId, challengedId, stakes } = result.challenge;
    // R1 (AUTH-4) — a challenge stored before the createClubChallenge check
    // may carry any stakes: never spawn a table on bad ones (it is closed with
    // no winner instead; nothing was bought in yet).
    const caStakes = validateChallengeStakes(stakes);
    if (!caStakes.ok) {
      resolveChallenge(challengeId, null).catch(() => {});
      socket.emit('error', { message: caStakes.error, code: caStakes.code });
      return;
    }

    // Spawn a heads-up table where the STAKES are the buy-in. Both players buy in
    // `stakes` via the normal join path; the winner takes the 2x pot when the
    // table tears down. No custom escrow — chips ride the proven join/cleanup
    // machinery (so a redeploy is covered by the same graceful cash-out as any
    // table).
    const bb = Math.max(2, Math.floor(stakes / 50));
    const sb = Math.max(1, Math.floor(bb / 2));
    const tableId = tableManager.createTable({
      tableName: 'Club Challenge',
      smallBlind: sb, bigBlind: bb,
      minBuyIn: stakes, maxBuyIn: stakes, maxPlayers: 2,
    } as any);
    if (!tableId) { socket.emit('error', { message: 'Could not start the challenge table' }); return; }
    // R2 (CLUBS-1) — registered BEFORE any await: from its creation the table
    // is a fixed-roster heads-up (quickTables: no AI backfill / fill / reload,
    // never listed; tableKindOf still 'club'), seats 0-1 only, joinable only by
    // its two players (joinTableRefusalReason).
    challengeTables.set(tableId, { challengeId, challengerId, challengedId });
    quickTables.add(tableId);
    const t = tableManager.getTable(tableId);
    if (t) {
      t.maxOccupiableSeats = Math.min(t.maxOccupiableSeats, 2);
      // Resolved on a challenger's bust — or when one of them leaves (the other
      // wins): quickGameEndCheck (format 'challenge'). The stakes are the
      // buy-ins: cleanupQuickTable cashes the winner's (and any remaining)
      // stack out, exactly once.
      registerQuickGame(tableId, t, { format: 'challenge', ownerUserId: null, ownerName: 'Club Challenge', entryFee: 0, challengeId });
    }
    await setChallengeTable(challengeId, tableId);

    // Tell BOTH participants to join the table.
    const payload = { challengeId, tableId, challengerId, challengedId, stakes };
    for (const [sid, a] of authSessions) {
      if (a.userId === challengerId || a.userId === challengedId) {
        io.sockets.sockets.get(sid)?.emit('clubChallengeAccepted', payload);
      }
    }
  });

  socket.on('declineClubChallenge', async (data: { challengeId: number }) => {
    const auth = authSessions.get(socket.id);
    if (!auth) { socket.emit('error', { message: 'Not authenticated' }); return; }
    const result = await declineChallenge(data.challengeId, auth.userId);
    if (result.success) {
      socket.emit('clubChallengeDeclined', { challengeId: data.challengeId });
    } else {
      socket.emit('error', { message: result.error });
    }
  });

  socket.on('getClubChallenges', async (data: { clubId: number }) => {
    // 2026-07-05 audit P2 fix: membership-gate (was leaking a private club's
    // pending/accepted challenge participants + stakes to any authenticated caller).
    if (!(await requireClubMember(data.clubId))) return;
    const result = await getClubChallenges(data.clubId);
    socket.emit('clubChallenges', result);
  });

  // ========== Table Scheduling ==========

  socket.on('scheduleClubTable', async (data: { clubId: number; config: any; scheduledTime: string; recurring: boolean; recurrencePattern?: string }) => {
    const auth = authSessions.get(socket.id);
    if (!auth) { socket.emit('error', { message: 'Not authenticated' }); return; }
    // 2026-10-11 (R1, AUTH-4) — the stored config becomes a real cash table
    // when it fires: validated now (and again when it is created).
    const stCheck = validateScheduledTableConfig(data?.config);
    if (!stCheck.ok) { socket.emit('error', { message: stCheck.error, code: stCheck.code }); return; }
    const result = await scheduleTable(data.clubId, auth.userId, stCheck.config, data.scheduledTime, data.recurring, data.recurrencePattern);
    if (result.success) {
      socket.emit('clubTableScheduled', result);
    } else {
      socket.emit('error', { message: result.error });
    }
  });

  socket.on('getScheduledClubTables', async (data: { clubId: number }) => {
    const result = await getScheduledTables(data.clubId);
    socket.emit('scheduledClubTables', result);
  });

  socket.on('activateScheduledClubTable', async (data: { id: number; clubId: number }) => {
    const auth = authSessions.get(socket.id);
    if (!auth) { socket.emit('error', { message: 'Not authenticated' }); return; }
    const result = await activateScheduledTable(data.id, auth.userId);
    if (result.success && result.tableConfig) {
      // 2026-07-07 gap-fill [10] — create via the shared helper so the manual
      // Activate button and the auto-fire sweep produce byte-identical tables.
      // F104 (2026-10-21) — for the scheduled ROW's club (the one the role
      // check used); the client's data.clubId named the table and its stats.
      const clubId = Number.isInteger(result.clubId) ? (result.clubId as number) : data.clubId;
      const made: { reason?: 'invalid_config' | 'retry' } = {};
      const tableId = await createTableFromScheduledConfig({ id: data.id, clubId }, result.tableConfig, made);
      if (!tableId) {
        // F104 fix-up — a DB failure is not "invalid settings": the row was put
        // back to 'scheduled' (Activate again, or it fires at its time).
        if (made.reason === 'retry') socket.emit('error', { message: 'Could not open the table right now — please try again.', code: 'scheduled_table_retry' });
        else socket.emit('error', { message: 'Invalid table settings for this scheduled table', code: 'invalid_table_config' });
        return;
      }
      socket.emit('scheduledClubTableActivated', { success: true, tableId, clubId });
    } else {
      socket.emit('error', { message: result.error });
    }
  });

  socket.on('deleteScheduledClubTable', async (data: { id: number }) => {
    const auth = authSessions.get(socket.id);
    if (!auth) { socket.emit('error', { message: 'Not authenticated' }); return; }
    const result = await deleteScheduledTable(data.id, auth.userId);
    if (result.success) {
      socket.emit('scheduledClubTableDeleted', { id: data.id });
    } else {
      socket.emit('error', { message: result.error });
    }
  });

  // ========== Custom Blind Structures ==========

  socket.on('createBlindStructure', async (data: { clubId: number; name: string; levels: any[] }) => {
    const auth = authSessions.get(socket.id);
    if (!auth) { socket.emit('error', { message: 'Not authenticated' }); return; }

    // Validate blind levels: SB > 0, BB >= 2*SB, ante >= 0, monotonically non-decreasing
    if (!Array.isArray(data.levels) || data.levels.length === 0 || data.levels.length > 30) {
      socket.emit('error', { message: 'Invalid blind structure' });
      return;
    }
    let prevBB = 0;
    for (const lvl of data.levels) {
      // 2026-07-07 gap-fill — the client sends smallBlind/bigBlind (ClubsPanel
      // builds levels with those keys), NOT sb/bb. Reading sb/bb yielded NaN, so
      // Number.isInteger(NaN) was always false and EVERY custom blind-structure
      // create was rejected with "Blind amounts must be integers". The DB fn
      // already stores smallBlind/bigBlind correctly; only this read was wrong.
      const sb = Number(lvl?.smallBlind);
      const bb = Number(lvl?.bigBlind);
      const ante = Number(lvl?.ante || 0);
      if (!Number.isInteger(sb) || !Number.isInteger(bb) || !Number.isInteger(ante)) {
        socket.emit('error', { message: 'Blind amounts must be integers' }); return;
      }
      if (sb <= 0 || bb < sb * 2 || ante < 0 || ante > sb) {
        socket.emit('error', { message: 'Invalid blind level (BB must be ≥ 2×SB, ante ≤ SB)' }); return;
      }
      if (bb < prevBB) {
        socket.emit('error', { message: 'Blinds must not decrease between levels' }); return;
      }
      prevBB = bb;
    }

    const result = await createBlindStructure(data.clubId, auth.userId, data.name, data.levels);
    if (result.success) {
      socket.emit('blindStructureCreated', result);
    } else {
      socket.emit('error', { message: result.error });
    }
  });

